PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE users (   id INTEGER PRIMARY KEY AUTOINCREMENT,   username TEXT UNIQUE NOT NULL,   email TEXT UNIQUE,   password_hash TEXT NOT NULL,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')) , is_admin INTEGER DEFAULT 0, shape_labels TEXT DEFAULT '["","","","","",""]');
CREATE TABLE sessions (     id TEXT PRIMARY KEY,     user_id INTEGER NOT NULL,     created_at TEXT NOT NULL DEFAULT (datetime('now')),     expires_at TEXT NOT NULL,     FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE   );
CREATE TABLE waza (     id INTEGER PRIMARY KEY AUTOINCREMENT,     "name_jp" TEXT,     "name_en" TEXT,     "name_en_literal" TEXT,     "name_en_gtranslate" TEXT,     "name_cn_gtranslate" TEXT,     "reference" TEXT,     "tag" TEXT,     "parent_jp0" TEXT,     "parent_en0" TEXT,     "parent_jp1" TEXT,     "parent_en1" TEXT,     "author_jp0" TEXT,     "author_en0" TEXT,     "author_jp1" TEXT,     "author_en1" TEXT,     "video0" TEXT,     "video1" TEXT,     "video2" TEXT,     "video3" TEXT,     "video4" TEXT,     "video5" TEXT,     "video6" TEXT,     "video7" TEXT,     "video8" TEXT,     "video9" TEXT,     UNIQUE(name_jp, name_en) );
CREATE TABLE contributions (     id INTEGER PRIMARY KEY AUTOINCREMENT,     user_id INTEGER NOT NULL REFERENCES users(id),     type TEXT NOT NULL,     waza_id INTEGER REFERENCES waza(id),     payload TEXT NOT NULL,     status TEXT NOT NULL DEFAULT 'pending',     admin_note TEXT,     created_at DATETIME NOT NULL DEFAULT (datetime('now')),     reviewed_at DATETIME );
CREATE TABLE IF NOT EXISTS "progress" (
    user_id    INTEGER NOT NULL,
    waza_id    INTEGER NOT NULL,
    markings   TEXT NOT NULL DEFAULT '[]',
    updated_at TEXT NOT NULL DEFAULT (datetime('now')),
    "like"     INTEGER CHECK ("like" IN (-1, 1) OR "like" IS NULL),
    PRIMARY KEY (user_id, waza_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (waza_id) REFERENCES waza(id) ON DELETE CASCADE
);
CREATE TABLE groups (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  name        TEXT    NOT NULL,
  join_policy TEXT    NOT NULL DEFAULT 'open'
                CHECK(join_policy IN ('open','approval','invite')),
  invite_key  TEXT    UNIQUE,
  social      TEXT,
  -- Nullable + ON DELETE SET NULL: created_by is record-keeping only
  -- (who originally created the group), not an active relationship.
  -- A user must be able to delete their account without that record
  -- blocking the deletion or leaving a dangling reference behind.
  created_by  INTEGER REFERENCES users(id) ON DELETE SET NULL,
  created_at  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE group_members (
  group_id  INTEGER NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
  user_id   INTEGER NOT NULL REFERENCES users(id)  ON DELETE CASCADE,
  role      TEXT    NOT NULL DEFAULT 'member'
              CHECK(role IN ('admin','member')),
  tag       TEXT,
  joined_at TEXT    NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (group_id, user_id)
);
CREATE TABLE group_applications (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  group_id   INTEGER NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
  user_id    INTEGER NOT NULL REFERENCES users(id)  ON DELETE CASCADE,
  status     TEXT    NOT NULL DEFAULT 'pending'
               CHECK(status IN ('pending','approved','rejected')),
  applied_at TEXT    NOT NULL DEFAULT (datetime('now'))
);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX idx_group_applications_one_pending
  ON group_applications(group_id, user_id)
  WHERE status = 'pending';
CREATE INDEX idx_progress_waza ON progress(waza_id);
CREATE INDEX idx_sessions_user ON sessions(user_id);
CREATE INDEX idx_sessions_expires ON sessions(expires_at);
CREATE INDEX idx_contributions_user   ON contributions(user_id);
CREATE INDEX idx_contributions_status ON contributions(status);
CREATE INDEX idx_group_members_user   ON group_members(user_id);
CREATE INDEX idx_group_members_group  ON group_members(group_id);
CREATE INDEX idx_group_applications_user  ON group_applications(user_id);
CREATE INDEX idx_group_applications_group ON group_applications(group_id);
CREATE INDEX idx_groups_invite_key ON groups(invite_key);
CREATE INDEX idx_groups_created_by_at ON groups(created_by, created_at);
